function kf2KutiklanCac2sex() {
	const s = 128;
	const desegnu = (reliefo) => kf2P2t6zoCac2sex(s, s, (kuns2bana) => {
		kuns2bana.fillStyle = reliefo ? "rgb(128,128,128)" : "rgb(208,176,136)";
		kuns2bana.fillRect(0, 0, s, s);
		for (let i = 0; i < 6; i++) {
			const y = (i + 1 / 2) / 6 * s;
			kuns2bana.strokeStyle = reliefo ? "rgba(64,64,64,0.55)" : "rgba(144,112,72,0.8)";
			kuns2bana.lineWidth = 2;
			kuns2bana.beginPath();
			kuns2bana.moveTo(0, y);
			kuns2bana.lineTo(s, y);
			kuns2bana.stroke();
		}
		for (let i = 0; i < 192; i++) {
			const x = Math.random() * s, y = Math.random() * s;
			const r = 19 / 32 + Math.random() * 35 / 32;
			kuns2bana.fillStyle = reliefo ? Math.random() < 1 / 2 ? "rgba(200,200,200,0.5)" : "rgba(80,80,80,0.45)" : Math.random() < 1 / 2 ? "rgba(232,208,176,0.5)" : "rgba(168,128,88,0.45)";
			kuns2bana.beginPath();
			kuns2bana.arc(x, y, r, 0, Math.PI * 2);
			kuns2bana.fill();
		}
	}, [1, 1], { volvado: RepeatWrapping });
	return {
		weh2: desegnu(false),
		reliefo: desegnu(true)
	};
}
new Vector3(0, 1, 0);
new Quaternion();
const sozasai = new Vector3(0, 1, 0);
function kf2Tubon(de, al, rDe, rAl) {
	const l6da = new Vector3().subVectors(al, de);
	const geometrio = new CylinderGeometry(rAl, rDe, l6da.length(), 6);
	geometrio.applyQuaternion(new Quaternion().setFromUnitVectors(sozasai, l6da.normalize()));
	geometrio.translate((de.x + al.x) / 2, (de.y + al.y) / 2, (de.z + al.z) / 2);
	return geometrio;
}
function kf2Artikon(n2k, r) {
	return new SphereGeometry(r, 6, 5).translate(n2k.x, n2k.y, n2k.z);
}
