const PETRELA_LARGHO = 14 / 16;
function spinoEn(z) {
	const n = PETRELA_SPINO.length;
	if (z <= PETRELA_SPINO[0].z) return {
		y: PETRELA_SPINO[0].y,
		r: PETRELA_SPINO[0].r
	};
	if (z >= PETRELA_SPINO[n - 1].z) return {
		y: PETRELA_SPINO[n - 1].y,
		r: PETRELA_SPINO[n - 1].r
	};
	for (let i = 0; i < n - 1; i++) {
		const a = PETRELA_SPINO[i], b = PETRELA_SPINO[i + 1];
		if (z >= a.z && z <= b.z) {
			const t = (z - a.z) / (b.z - a.z);
			return {
				y: a.y + (b.y - a.y) * t,
				r: a.r + (b.r - a.r) * t
			};
		}
	}
	return {
		y: 0,
		r: 0
	};
}
function surfacxaPunkto(s, z, tafkaq) {
	const spino = spinoEn(z);
	return new Vector3(s * Math.cos(tafkaq) * spino.r * PETRELA_LARGHO, spino.y + Math.sin(tafkaq) * spino.r, z);
}
function vPorZ(z) {
	const n = PETRELA_SPINO.length;
	const limigita = Math.min(PETRELA_SPINO[n - 1].z, Math.max(PETRELA_SPINO[0].z, z));
	for (let i = 0; i < n - 1; i++) {
		const a = PETRELA_SPINO[i], b = PETRELA_SPINO[i + 1];
		if (limigita >= a.z && limigita <= b.z) {
			const t = (limigita - a.z) / (b.z - a.z);
			return (i + t) / (n - 1);
		}
	}
	return 1;
}
function kf2Lofton(stacioj, subdividoj, hatafkaq, sefini) {
	const n = stacioj.length;
	const je = (i) => stacioj[Math.max(0, Math.min(n - 1, i))];
	const skek2 = (i, t, bok) => katmullRom(bok(je(i - 1)), bok(je(i)), bok(je(i + 1)), bok(je(i + 2)), t);
	const kofj = [];
	for (let i = 0; i < n - 1; i++) for (let k = 0; k < subdividoj; k++) {
		const t = k / subdividoj;
		kofj.push({
			z: skek2(i, t, (s) => s.z),
			y: skek2(i, t, (s) => s.y),
			r: skek2(i, t, (s) => s.r)
		});
	}
	kofj.push(je(n - 1));
	const haxekuxa = [];
	const qan2k = [];
	const havecax2lani = [];
	const c2q = hatafkaq + 1;
	for (let i = 0; i < kofj.length; i++) {
		const stacio = kofj[i];
		for (let j = 0; j <= hatafkaq; j++) {
			const tafkaq = j / hatafkaq * Math.PI * 2;
			const cos = Math.cos(tafkaq), sin = Math.sin(tafkaq);
			const vertikala = sin < 0 ? stacio.r * 9 / 8 : stacio.r;
			haxekuxa.push(cos * stacio.r * sefini, stacio.y + sin * vertikala, stacio.z);
			qan2k.push(j / hatafkaq, i / (kofj.length - 1));
		}
	}
	for (let i = 0; i < kofj.length - 1; i++) for (let j = 0; j < hatafkaq; j++) {
		const a = i * c2q + j, b = a + 1;
		const c = a + c2q, d = b + c2q;
		havecax2lani.push(a, b, d, a, d, c);
	}
	return kf2LoftoQoxa(haxekuxa, qan2k, havecax2lani);
}
