const KUBUTA_INDESKO = 4;
const KUBUTA_X = FLUGILAJ_RIPOJ[KUBUTA_INDESKO].x;
function kf2Flugilon(ripoj, uDe, uAl, subdividoj, hatafkaq) {
	const n = ripoj.length;
	const je = (i) => ripoj[Math.max(0, Math.min(n - 1, i))];
	const skek2 = (i, t, bok) => katmullRom(bok(je(i - 1)), bok(je(i)), bok(je(i + 1)), bok(je(i + 2)), t);
	const kofj = [];
	for (let i = 0; i < n - 1; i++) for (let k = 0; k < subdividoj; k++) {
		const t = k / subdividoj;
		kofj.push({
			x: skek2(i, t, (r) => r.x),
			y: skek2(i, t, (r) => r.y),
			antauxo: skek2(i, t, (r) => r.antauxo),
			malantauxo: skek2(i, t, (r) => r.malantauxo),
			dikeco: skek2(i, t, (r) => r.dikeco)
		});
	}
	kofj.push(je(n - 1));
	const haxekuxa = [];
	const qan2k = [];
	const havecax2lani = [];
	const c2q = hatafkaq + 1;
	for (let i = 0; i < kofj.length; i++) {
		const ripo = kofj[i];
		const u = uDe + (uAl - uDe) * (i / (kofj.length - 1));
		for (let j = 0; j <= hatafkaq; j++) {
			const tafkaq = j / hatafkaq * Math.PI * 2;
			const cos = Math.cos(tafkaq), sin = Math.sin(tafkaq);
			const kordo = (1 + cos) / 2;
			haxekuxa.push(ripo.x, ripo.y - sin * ripo.dikeco / 2, ripo.malantauxo + kordo * (ripo.antauxo - ripo.malantauxo));
			qan2k.push(u, kordo);
		}
	}
	for (let i = 0; i < kofj.length - 1; i++) for (let j = 0; j < hatafkaq; j++) {
		const a = i * c2q + j, b = a + 1;
		const c = a + c2q, d = b + c2q;
		havecax2lani.push(a, b, d, a, d, c);
	}
	return kf2LoftoQoxa(haxekuxa, qan2k, havecax2lani);
}
function kunfandiPoPukek(hakek) {
	const haca1ara = /* @__PURE__ */ new Map();
	for (const p of hakek) {
		const pukek = p.material;
		const ca1ara = haca1ara.get(pukek);
		if (ca1ara) ca1ara.push(p);
		else haca1ara.set(pukek, [p]);
	}
	const kunfandajxoj = [];
	for (const [pukek, ca1ara] of haca1ara) {
		if (ca1ara.length === 1) {
			kunfandajxoj.push({
				cakamaha: ca1ara[0],
				hatsiq: ca1ara
			});
			continue;
		}
		const geometrioj = ca1ara.map((p) => {
			p.updateMatrix();
			return p.geometry.clone().applyMatrix4(p.matrix);
		});
		const veb6kekita = mergeGeometries(geometrioj, false);
		for (const g of geometrioj) g.dispose();
		if (veb6kekita) kunfandajxoj.push({
			cakamaha: new Mesh(veb6kekita, pukek),
			hatsiq: ca1ara
		});
	}
	return kunfandajxoj;
}
function vepaqPetrelanModelon() {
	const hate = new Group();
	const cac2sex = petrelajCac2sex(vPorZ);
	const g2j6 = new MeshStandardMaterial({
		color: 16777215,
		map: cac2sex.korpo,
		bumpMap: cac2sex.korpoBump,
		bumpScale: 1 / 128,
		roughness: 3 / 4,
		metalness: 0
	});
	const flugilaPukek = new MeshStandardMaterial({
		color: 16777215,
		map: cac2sex.flugilo,
		bumpMap: cac2sex.flugiloBump,
		bumpScale: 1 / 128,
		roughness: 3 / 4,
		metalness: 0,
		side: 2
	});
	const hunasai = new MeshStandardMaterial({
		color: 1052696,
		roughness: 1 / 4,
		metalness: 0
	});
	const korpo = new Mesh(kf2Lofton(PETRELA_SPINO, 4, 16, PETRELA_LARGHO), g2j6);
	korpo.name = "korpo";
	hate.add(korpo);
	const beko = new Mesh(kf2Lofton([
		{
			z: 48 / 128,
			y: 14 / 128,
			r: 2 / 128
		},
		{
			z: 54 / 128,
			y: 14 / 128,
			r: 6 / 512
		},
		{
			z: 58 / 128,
			y: 13 / 128,
			r: 5 / 512
		},
		{
			z: 61 / 128,
			y: 11 / 128,
			r: 3 / 512
		}
	], 3, 8, 6 / 8), hunasai);
	beko.name = "beko";
	hate.add(beko);
	const naztubo = new Mesh(new CylinderGeometry(6 / 512, 6 / 512, 4 / 64, 6), hunasai);
	naztubo.rotation.x = Math.PI / 2 - 1 / 16;
	naztubo.position.set(0, 15 / 128, 52 / 128);
	hate.add(naztubo);
	const T2BANU_Z = 40 / 128, T2BANU_ANGULO = 7 / 16;
	const t2banuRadiuso = 5 / 512;
	for (const s of [1, -1]) {
		const soza = surfacxaPunkto(s, T2BANU_Z, T2BANU_ANGULO);
		const interna = new Vector3(s * Math.cos(T2BANU_ANGULO), Math.sin(T2BANU_ANGULO), 0).multiplyScalar(t2banuRadiuso * 1 / 2);
		const okulo = new Mesh(new SphereGeometry(t2banuRadiuso, 8, 8), hunasai);
		okulo.position.copy(soza).sub(interna);
		okulo.name = "okulo";
		hate.add(okulo);
	}
	for (const s of [1, -1]) {
		const piedo = new Mesh(new SphereGeometry(8 / 512, 8, 8), hunasai);
		piedo.scale.set(5 / 8, 5 / 8, 14 / 8);
		piedo.position.set(s * 12 / 512, -8 / 64, -28 / 128);
		hate.add(piedo);
	}
	const vostaGrupo = new Group();
	vostaGrupo.name = "vosto";
	vostaGrupo.position.set(0, 2 / 128, -40 / 128);
	const vostaj = [];
	for (let k = -2; k <= 2; k++) {
		const sahakani = 13 / 64 - Math.abs(k) * 1 / 64;
		const p2somani = 3 / 128;
		const qoxa = new Shape();
		qoxa.moveTo(0, -.0234375);
		qoxa.quadraticCurveTo(sahakani * 7 / 8, -.2109375 / 8, sahakani, 0);
		qoxa.quadraticCurveTo(sahakani * 7 / 8, p2somani * 9 / 8, 0, p2somani);
		qoxa.closePath();
		const plumo = new ExtrudeGeometry(qoxa, {
			depth: 4 / 512,
			bevelEnabled: false,
			curveSegments: 8
		});
		plumo.rotateX(Math.PI / 2);
		plumo.rotateY(Math.PI / 2 + k * 11 / 64);
		plumo.translate(0, 1 / 128, 0);
		vostaj.push(plumo);
	}
	const vostajVeb6kekitaj = mergeGeometries(vostaj, false);
	for (const g of vostaj) g.dispose();
	if (vostajVeb6kekitaj) {
		const vostaCakamaha = new Mesh(vostajVeb6kekitaj, g2j6);
		vostaCakamaha.name = "vostoplumoj";
		vostaGrupo.add(vostaCakamaha);
		hate.add(vostaGrupo);
	}
	const brakaGeometrio = kf2Flugilon(FLUGILAJ_RIPOJ.slice(0, 5), 0, 42 / 64, 3, 10);
	const manaGeometrio = kf2Flugilon(FLUGILAJ_RIPOJ.slice(KUBUTA_INDESKO).map((r) => ({
		...r,
		x: r.x - KUBUTA_X
	})), 42 / 64, 1, 3, 10);
	for (const s of [1, -1]) {
		const flugilaGrupo = new Group();
		flugilaGrupo.name = "flugilo";
		flugilaGrupo.position.set(-s * 6 / 64, 9 / 128, 13 / 64);
		const spegulo = -s;
		const knece = new Mesh(brakaGeometrio, flugilaPukek);
		knece.name = "brako";
		knece.scale.x = spegulo;
		flugilaGrupo.add(knece);
		const manoGrupo = new Group();
		manoGrupo.name = "mano";
		manoGrupo.position.set(-s * KUBUTA_X, 0, 0);
		manoGrupo.scale.x = spegulo;
		const mano = new Mesh(manaGeometrio, flugilaPukek);
		mano.name = "mano";
		manoGrupo.add(mano);
		flugilaGrupo.add(manoGrupo);
		hate.add(flugilaGrupo);
	}
	const statikaj = hate.children.filter((c) => c.isMesh);
	for (const k of kunfandiPoPukek(statikaj)) {
		if (k.hatsiq.length === 1) continue;
		for (const m of k.hatsiq) hate.remove(m);
		hate.add(k.cakamaha);
	}
	return hate;
}
