	s.quadraticCurveTo(ht, eh, ht - r, eh);
	s.lineTo(-ht + r, eh);
	s.quadraticCurveTo(-ht, eh, -ht - d, eh - r);
	s.lineTo(-hb + d, r);
	s.quadraticCurveTo(-hb, 0, -hb + d, -r);
