		flamaEkst6lima,
		flamaInterno,
		flamaKerno,
		flamaLangoj,
		langojPoLampo: LANGOJ,
		langajBazoj,
		langajFazoj,
		brilajPunktoj,
		brilaPukek,
		punktajLumoj,
		lumajIndeksoj,
		spots: flamajLokoj,
